<?php defined('BASEPATH') OR exit('No direct script access allowed');class Billing extends MY_Controller{function __construct(){parent::__construct();$this->load->model('Billing_model','billing');}private function admin(){if(!$c=$this->require_auth())return NULL;$this->load->model('Admin_model','admin');if(!$this->admin->access($c['sub'],$c['organizationId']??NULL)){$this->fail('FORBIDDEN','Administrator access required',403);return NULL;}return $c;}function index(){if(!$c=$this->admin())return;if($this->input->method(TRUE)==='PATCH'){$d=$this->body();if(isset($d['plan'])&&!in_array($d['plan'],array('starter','pro','team','enterprise'),TRUE)||isset($d['cycle'])&&!in_array($d['cycle'],array('monthly','annual'),TRUE)||isset($d['seats'])&&($d['seats']<1||$d['seats']>10000))return $this->fail('VALIDATION_ERROR','Invalid subscription update',422);return $this->respond($this->billing->update_sub($c['organizationId'],$d));}return $this->respond($this->billing->overview($c['organizationId']));}function invoice($id,$action){if(!$c=$this->admin())return;$reason=$this->body()['reason']??NULL;$r=$this->billing->invoice_action($id,$c['organizationId'],$action==='mark-paid'?'paid':'void',$reason);return $r?$this->respond($r):$this->fail('NOT_FOUND','Invoice not found',404);}function webhook(){if(!hash_equals((string)getenv('VP_WEBHOOK_SECRET'),(string)$this->input->get_request_header('X-Windels-Webhook-Secret',TRUE)))return $this->fail('UNAUTHORIZED','Invalid webhook secret',401);$d=$this->body();foreach(array('eventId','invoiceNumber','status') as $f)if(empty($d[$f]))return $this->fail('VALIDATION_ERROR',$f.' required',422);return $this->respond($this->billing->payment($d));}function insights(){if(!$c=$this->admin())return;$since=date('Y-m-d H:i:s',strtotime('-30 days'));$count=function($table,$field='created_at')use($since){return $this->db->where($field.' >=',$since)->count_all_results($table);};$usage=array('workflows30d'=>$count('workflow_runs'),'messages30d'=>$count('messages')+$count('talk_messages'),'conversations30d'=>$count('conversations'),'tasks30d'=>$count('tasks'),'agentsActive'=>$this->db->where('last_activity_at >=',$since)->count_all_results('agents'),'revenueCents30d'=>(int)($this->db->select_sum('amount_cents','n')->where(array('status'=>'paid'))->where('created_at >=',$since)->get('payment_records')->row_array()['n']??0));return $this->respond(array('period'=>array('since'=>$since,'until'=>date('c')),'usage'=>$usage,'forecast30d'=>array('workflows'=>$usage['workflows30d'],'messages'=>$usage['messages30d'],'conversations'=>$usage['conversations30d'],'tasks'=>$usage['tasks30d']),'insights'=>array('Forecast uses the latest 30-day measured activity without invented growth assumptions.')));}}
